import json,pathlib,collections
root=pathlib.Path(__file__).resolve().parent
acq=json.loads((root/'data/acquisitions.json').read_text());cs=json.loads((root/'data/candidates.json').read_text())
lines=['# Research coverage — 30 October 2026 (America/New_York)','','Recent search: **1 August–30 October 2026**, inclusive query boundaries (90-day lookback). Publication date means first publication, not registry update or print issue date. Retrieved UTC timestamps and API queries are retained in acquisition runs.','','Acquisition source: Europe PMC core API, MED records, original author abstracts indexed from journals. These are metadata/limited-passage verification, not full-text clinical review. No ESMO abstract results, guideline conclusions or current regulatory labels have been released.','','## Executed search inventory','','|Family|Indexed hits|Fetched|Result|Watermark|','|---|---:|---:|---|---|']
for r in acq['runs']:
 if r.get('mode')=='pivotal-context':continue
 lines.append(f"|{r['family']}|{r.get('hit_count','unknown')}|{r.get('fetched',0)}|{r['status']}|{r.get('watermark') or 'not advanced'}|")
lines+=['','All lung results within the configured limit were fetched. Other family searches deliberately stop at 30 records; they are partial and have no completed watermark. Query hits include irrelevant reviews and non-oncology reports; the curated subset is separately inspected. Failed/partial runs never mean no new research.','','## Candidate collection','','**21 pending human review: 15 Lung (8 NSCLC and 7 SCLC), plus six other-family examples.** No reviewer identities or approval timestamps have been fabricated. Deterministic classification is provisional. Numeric outcomes were deliberately not extracted without their complete endpoint/analysis context.','','|PMID|First publication|Family|Provisional specialties|Study identifier|Original report / abstract|','|---|---|---|---|---|---|']
for c in cs:
 s=c['sources'][0];lines.append(f"|{s['pmid']}|{s['published_date']}|{', '.join(c['cancer_families'])}|{', '.join(c['specialties'])}|{', '.join(c['study_ids'])}|[{c['title']}]({s['url']})|")
lines+=['','## Older pivotal context, acquired separately','','These are not counted as recent efficacy reports. They remain unreleased source metadata, with study/report links preserved.']
for s in acq['documents']:
 if s['pmid'] in ['37272513','39268857']:lines.append(f"- [{s['title']}]({s['url']}), first published {s['published_date']}; DOI {s['doi']}; trial identifiers {s['study_ids']}.")
lines+=['','## Unverified leads and explicit exclusions','','- SAFFRON / post-osimertinib MET example from the original brief: no supporting primary report ingested; remains a lead, not a result or approval claim.','- Daraxonrasib pancreatic approval example: no regulator source ingested; no approval conclusion permitted.','- ESMO 2026 official landing page and third-party dates are discoverable, but official abstract results/access were not acquired. No candidate is represented as a verified ESMO presentation.','- Publisher pages for MDT-BRIDGE and tambotatug were found as corroborating original sources; retained evidence remains explicitly abstract-only. No paywall or access challenge was bypassed.','- Several selected reports lack an NCT in their accessible abstract. Their unresolved report IDs are not asserted to be distinct trials.','- Current FDA labeling, funding, conflicts, full inclusion/exclusion and geography require review. Unknown is retained explicitly.','- Guideline collection, other-language coverage, broad rare-cancer coverage and non-indexed congress abstracts are incomplete. The Other sample is melanoma only.','','## Verified acquisition references','','- [Europe PMC REST API](https://europepmc.org/RestfulWebService): public core/search endpoint executed successfully with cursorMark, resultType=core and SRC:MED. Documentation page returned 403 in web tooling; API behavior was verified directly, without circumventing that page.','- [EMBL-EBI terms](https://www.ebi.ac.uk/about/terms-of-use/): terms retain original data-owner rights; metadata access does not grant blanket full-text redistribution. Only metadata and a maximum 24-word abstract excerpt per source were retained.','- [ClinicalTrials.gov API documentation](https://clinicaltrials.gov/data-api/api): documentation inspected; registry connector disabled, not tested for ingestion.','- [Databricks Statement Execution API](https://docs.databricks.com/aws/en/dev-tools/sql-execution-tutorial): supported authorized CLI/OAuth transport executed against the designated workspace.']
(root/'RESEARCH-COVERAGE.md').write_text('\n'.join(lines)+'\n')
print('documents',len(acq['documents']),'candidates',len(cs),'subtypes',dict(collections.Counter(x for c in cs for x in c['subtypes'])))
